<?php
namespace App\Http\Controllers\Api;
use App\Http\Resources\CategoryResource; use App\Http\Resources\ProductResource; use App\Models\Category; use App\Models\Product; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request;
/** @group Catalog */ class CatalogController extends ApiController { public function categories():JsonResponse{return $this->success(CategoryResource::collection(Category::where('is_active',true)->orderBy('sort_order')->get()));} public function products(Request $r):JsonResponse{$q=Product::with(['variants'=>fn($q)=>$q->where('is_active',true),'modifierGroups.options'])->where('is_active',true)->orderBy('sort_order');$q->when($r->filled('category_id'),fn($q)=>$q->where('category_id',$r->integer('category_id')));$q->when($r->has('is_available'),fn($q)=>$q->where('is_available',$r->boolean('is_available')));return $this->success(ProductResource::collection($q->get()));} public function product(Product $product):JsonResponse{abort_unless($product->is_active,404);return $this->success(new ProductResource($product->load(['variants'=>fn($q)=>$q->where('is_active',true),'modifierGroups.options'])));}}
